SELECT e.id AS entry_signal, e.symbol, e.generated_at AS entry_gen, (SELECT CONCAT(f.id,'|',f.decision,'|',f.original_decision,'|',f.total_score,'|',f.generated_at) FROM crypto_ai.trade_signal f WHERE f.symbol=e.symbol AND f.interval_code='5m' AND f.generated_at<=e.generated_at ORDER BY f.generated_at DESC LIMIT 1) AS five_visible, (SELECT CONCAT(f.id,'|',f.decision,'|',f.original_decision,'|',f.total_score,'|',f.generated_at) FROM crypto_ai.trade_signal f WHERE f.symbol=e.symbol AND f.interval_code='5m' AND f.generated_at>e.generated_at AND f.generated_at<=e.generated_at + INTERVAL 5 SECOND ORDER BY f.generated_at LIMIT 1) AS five_racing, (SELECT CONCAT(h.id,'|',h.decision,'|',h.original_decision,'|',h.total_score,'|',h.generated_at) FROM crypto_ai.trade_signal h WHERE h.symbol=e.symbol AND h.interval_code='1h' AND h.generated_at<=e.generated_at ORDER BY h.generated_at DESC LIMIT 1) AS one_h_visible FROM crypto_ai.trade_signal e WHERE e.id IN (156723,159408,165412,167668,171589,176710) ORDER BY e.id;